SET NOCOUNT ON; SET XACT_ABORT ON;
IF DB_NAME() <> N'TTSmart_Operational_V1_Test' OR NOT EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=7) THROW 58800,N'Thiếu tiền điều kiện.',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=8 AND ScriptChecksum='$(ScriptChecksum)') RETURN;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=8) THROW 58801,N'Checksum không khớp.',1;
BEGIN TRANSACTION;
DECLARE @OperationalMigrationLockResult int;
EXEC @OperationalMigrationLockResult = sys.sp_getapplock @Resource=N'TTSmart.Operational.V1.Baseline', @LockMode=N'Exclusive', @LockOwner=N'Transaction', @LockTimeout=60000;
IF @OperationalMigrationLockResult < 0 THROW 58890,N'Không lấy được application lock Operational v1.',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=8 AND ScriptChecksum='$(ScriptChecksum)') BEGIN COMMIT; RETURN; END;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE ModuleCode=N'Operational' AND MigrationNumber=8) THROW 58801,N'Checksum không khớp.',1;
CREATE TABLE dbo.Stations (StationId uniqueidentifier NOT NULL CONSTRAINT PK_Stations PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, StationCode nvarchar(100) NOT NULL, Name nvarchar(300) NULL, ImageUrl nvarchar(2000) NULL, Location nvarchar(1000) NULL, AllowPublicSignup bit NULL, RegistrationPublicKey nvarchar(500) NULL, RegistrationGrantedAtUtc datetime2(7) NULL, SourceCreatedAtUtc datetime2(7) NULL, SourceUpdatedAtUtc datetime2(7) NULL, MigratedAtUtc datetime2(7) NULL, CreatedAtUtc datetime2(7) NULL, UpdatedAtUtc datetime2(7) NULL, Version int NOT NULL CONSTRAINT DF_Stations_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT UQ_Stations_PublicId UNIQUE(PublicId), CONSTRAINT UQ_Stations_Code UNIQUE(StationCode), CONSTRAINT CK_Stations_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_Stations_Version CHECK(Version>=0));
CREATE TABLE dbo.StationFiles (StationFileId uniqueidentifier NOT NULL CONSTRAINT PK_StationFiles PRIMARY KEY, StationId uniqueidentifier NOT NULL, FileId uniqueidentifier NULL, ExternalUrl nvarchar(2000) NULL, Label nvarchar(300) NULL, SortOrder int NOT NULL CONSTRAINT DF_StationFiles_Sort DEFAULT 0, CONSTRAINT FK_StationFiles_Station FOREIGN KEY(StationId) REFERENCES dbo.Stations(StationId), CONSTRAINT FK_StationFiles_File FOREIGN KEY(FileId) REFERENCES dbo.Files(FileId), CONSTRAINT CK_StationFiles_Reference CHECK((FileId IS NULL AND ExternalUrl IS NOT NULL) OR (FileId IS NOT NULL AND ExternalUrl IS NULL)));
CREATE TABLE dbo.StationProducts (StationProductId uniqueidentifier NOT NULL CONSTRAINT PK_StationProducts PRIMARY KEY, StationId uniqueidentifier NOT NULL, ProductId uniqueidentifier NOT NULL, SortOrder int NOT NULL CONSTRAINT DF_StationProducts_Sort DEFAULT 0, CONSTRAINT FK_StationProducts_Station FOREIGN KEY(StationId) REFERENCES dbo.Stations(StationId), CONSTRAINT FK_StationProducts_Product FOREIGN KEY(ProductId) REFERENCES dbo.Products(ProductId), CONSTRAINT UQ_StationProducts_Station_Product UNIQUE(StationId,ProductId));
CREATE TABLE dbo.UserStations (UserStationId uniqueidentifier NOT NULL CONSTRAINT PK_UserStations PRIMARY KEY, UserId uniqueidentifier NOT NULL, StationId uniqueidentifier NOT NULL, CONSTRAINT FK_UserStations_User FOREIGN KEY(UserId) REFERENCES dbo.Users(UserId), CONSTRAINT FK_UserStations_Station FOREIGN KEY(StationId) REFERENCES dbo.Stations(StationId), CONSTRAINT UQ_UserStations_User_Station UNIQUE(UserId,StationId));
CREATE TABLE dbo.StorefrontSettings (StorefrontSettingId uniqueidentifier NOT NULL CONSTRAINT PK_StorefrontSettings PRIMARY KEY, SingletonKey tinyint NOT NULL, FooterLogoUrl nvarchar(2000) NULL, FooterDescription nvarchar(max) NULL, FooterAddress nvarchar(1000) NULL, FooterPhone nvarchar(100) NULL, FooterEmail nvarchar(320) NULL, IntroductionContent nvarchar(max) NULL, MainPolicy nvarchar(max) NULL, NewProductUrl nvarchar(2000) NULL, TopPurchaseUrl nvarchar(2000) NULL, HighestRatingUrl nvarchar(2000) NULL, DefaultLanguage nvarchar(20) NULL, DisplayPartners bit NULL, HomeCategoryConfigured bit NULL, HomeCategorySidebarTitle nvarchar(300) NULL, ShowSidebar bit NULL, ShowQuickCategories bit NULL, SourceCreatedAtUtc datetime2(7) NULL, SourceUpdatedAtUtc datetime2(7) NULL, MigratedAtUtc datetime2(7) NULL, CreatedAtUtc datetime2(7) NULL, UpdatedAtUtc datetime2(7) NULL, Version int NOT NULL CONSTRAINT DF_StorefrontSettings_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT UQ_StorefrontSettings_Singleton UNIQUE(SingletonKey), CONSTRAINT CK_StorefrontSettings_Singleton CHECK(SingletonKey=1), CONSTRAINT CK_StorefrontSettings_Version CHECK(Version>=0));
CREATE TABLE dbo.StorefrontLocalizedContents (StorefrontLocalizedContentId uniqueidentifier NOT NULL CONSTRAINT PK_StorefrontLocalizedContents PRIMARY KEY, ContentKey nvarchar(100) NOT NULL, LanguageCode nvarchar(20) NOT NULL, Title nvarchar(300) NULL, Content nvarchar(max) NULL, CONSTRAINT UQ_StorefrontLocalizedContents_Key_Language UNIQUE(ContentKey,LanguageCode));
CREATE TABLE dbo.StorefrontImages (StorefrontImageId uniqueidentifier NOT NULL CONSTRAINT PK_StorefrontImages PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, FileId uniqueidentifier NULL, ExternalUrl nvarchar(2000) NULL, ImageType nvarchar(30) NOT NULL, SortOrder int NOT NULL CONSTRAINT DF_StorefrontImages_Sort DEFAULT 0, CONSTRAINT FK_StorefrontImages_File FOREIGN KEY(FileId) REFERENCES dbo.Files(FileId), CONSTRAINT UQ_StorefrontImages_PublicId UNIQUE(PublicId), CONSTRAINT CK_StorefrontImages_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_StorefrontImages_Reference CHECK((FileId IS NULL AND ExternalUrl IS NOT NULL) OR (FileId IS NOT NULL AND ExternalUrl IS NULL)));
CREATE TABLE dbo.StorefrontSections (StorefrontSectionId uniqueidentifier NOT NULL CONSTRAINT PK_StorefrontSections PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, Name nvarchar(300) NULL, IsDisplayed bit NULL, ImageUrl nvarchar(2000) NULL, LinkUrl nvarchar(2000) NULL, SortOrder int NOT NULL CONSTRAINT DF_StorefrontSections_Sort DEFAULT 0, SourcePath nvarchar(1000) NULL, Version int NOT NULL CONSTRAINT DF_StorefrontSections_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT UQ_StorefrontSections_PublicId UNIQUE(PublicId), CONSTRAINT CK_StorefrontSections_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_StorefrontSections_Version CHECK(Version>=0));
CREATE TABLE dbo.StorefrontSectionProducts (StorefrontSectionProductId uniqueidentifier NOT NULL CONSTRAINT PK_StorefrontSectionProducts PRIMARY KEY, StorefrontSectionId uniqueidentifier NOT NULL, ProductId uniqueidentifier NOT NULL, SortOrder int NOT NULL CONSTRAINT DF_StorefrontSectionProducts_Sort DEFAULT 0, CONSTRAINT FK_StorefrontSectionProducts_Section FOREIGN KEY(StorefrontSectionId) REFERENCES dbo.StorefrontSections(StorefrontSectionId), CONSTRAINT FK_StorefrontSectionProducts_Product FOREIGN KEY(ProductId) REFERENCES dbo.Products(ProductId), CONSTRAINT UQ_StorefrontSectionProducts_Section_Product UNIQUE(StorefrontSectionId,ProductId));
CREATE TABLE dbo.HomeCategories (HomeCategoryId uniqueidentifier NOT NULL CONSTRAINT PK_HomeCategories PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, LegacyId nvarchar(200) NULL, Name nvarchar(300) NULL, CategoryType nvarchar(100) NULL, LinkUrl nvarchar(2000) NULL, IconKey nvarchar(300) NULL, ImageUrl nvarchar(2000) NULL, ShowSidebar bit NULL, ShowQuick bit NULL, SortOrder int NOT NULL CONSTRAINT DF_HomeCategories_Sort DEFAULT 0, SourcePath nvarchar(1000) NULL, CONSTRAINT UQ_HomeCategories_PublicId UNIQUE(PublicId), CONSTRAINT CK_HomeCategories_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24));
CREATE TABLE dbo.Policies (PolicyId uniqueidentifier NOT NULL CONSTRAINT PK_Policies PRIMARY KEY, PublicId char(24) COLLATE Latin1_General_100_BIN2 NOT NULL, PolicyKey nvarchar(50) NOT NULL, Title nvarchar(300) NULL, Summary nvarchar(max) NULL, SourceUpdatedAtUtc datetime2(7) NULL, Version int NOT NULL CONSTRAINT DF_Policies_Version DEFAULT 0, RowVersion rowversion NOT NULL, CONSTRAINT UQ_Policies_PublicId UNIQUE(PublicId), CONSTRAINT UQ_Policies_Key UNIQUE(PolicyKey), CONSTRAINT CK_Policies_PublicId CHECK(PublicId NOT LIKE '%[^0-9a-f]%' AND LEN(PublicId)=24), CONSTRAINT CK_Policies_Version CHECK(Version>=0));
CREATE TABLE dbo.PolicySections (PolicySectionId uniqueidentifier NOT NULL CONSTRAINT PK_PolicySections PRIMARY KEY, PolicyId uniqueidentifier NOT NULL, Title nvarchar(300) NULL, Content nvarchar(max) NULL, SortOrder int NOT NULL CONSTRAINT DF_PolicySections_Sort DEFAULT 0, SourcePath nvarchar(1000) NULL, CONSTRAINT FK_PolicySections_Policy FOREIGN KEY(PolicyId) REFERENCES dbo.Policies(PolicyId));
INSERT dbo.SchemaVersions SELECT NEWID(),N'Operational',8,N'008_CreateStorefrontAndStationTables.sql','$(ScriptChecksum)',SYSUTCDATETIME(),ORIGINAL_LOGIN(); COMMIT;
GO
